# Phase 1: rate a resolved ticket

Class: ACT, but tenant scoping is a hot path (independent review in phase 5). Spec requirements 1, 2, 3.
Context: `src/portal.js:10-14` (`getMyTicket` returns null for a ticket of another organisation or a missing one: reuse it so both give the same answer), `src/tickets.js:7-20` (`createTicket` row), `docs/glossary.md` (closed is final).

## Files
- Create `test/rating.test.js`.
- Modify `src/tickets.js` (new ticket row gets `rating_score: null, rated_at: null`).
- Modify `src/portal.js` (add `rateTicket`, export it).

## Steps
- [ ] 1. Create `test/rating.test.js`:
```js
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createStore } = require('../src/store');
const { STATUS, createTicket, assignTicket, resolveTicket } = require('../src/tickets');
const { closeResolved } = require('../src/jobs/close-resolved');
const portal = require('../src/portal');

const DAY = 24 * 60 * 60 * 1000;
const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);
const acme = { id: 7, orgId: 1 };
const globex = { id: 9, orgId: 2 };

function resolved(store) {
  const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'Printer', body: 'x', now: at(0) });
  assignTicket(store, t.id, 41);
  resolveTicket(store, t.id, 41, { now: at(1) });
  return t;
}

test('a customer rates a resolved ticket of their organisation and it is stored with the score and time', () => {
  const store = createStore();
  const t = resolved(store);
  portal.rateTicket(store, acme, t.id, 4, { now: at(2) });
  const stored = store.getTicket(t.id);
  assert.equal(stored.rating_score, 4);
  assert.equal(stored.rated_at, at(2).toISOString());
});

test('a score that is not a whole number from 1 to 5 is refused', () => {
  const store = createStore();
  const t = resolved(store);
  for (const bad of [0, 6, 2.5, -1, '4', NaN, null, undefined]) {
    assert.throws(() => portal.rateTicket(store, acme, t.id, bad), /whole number from 1 to 5/);
  }
  assert.equal(store.getTicket(t.id).rating_score, null);
});

test('an open, pending or closed ticket cannot be rated', () => {
  const store = createStore();
  const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'Printer', body: 'x', now: at(0) });
  assert.throws(() => portal.rateTicket(store, acme, t.id, 5), /cannot rate a open ticket/);
  store.updateTicket(t.id, { status: STATUS.PENDING });
  assert.throws(() => portal.rateTicket(store, acme, t.id, 5), /cannot rate a pending ticket/);
  resolveTicket(store, t.id, 41, { now: at(1) });
  closeResolved(store, { now: at(5) });
  assert.throws(() => portal.rateTicket(store, acme, t.id, 5), /cannot rate a closed ticket/);
  assert.equal(store.getTicket(t.id).rating_score, null);
});

test('a second rating is refused and the first stays', () => {
  const store = createStore();
  const t = resolved(store);
  portal.rateTicket(store, acme, t.id, 4, { now: at(2) });
  assert.throws(() => portal.rateTicket(store, acme, t.id, 1, { now: at(3) }), /already rated/);
  const stored = store.getTicket(t.id);
  assert.equal(stored.rating_score, 4);
  assert.equal(stored.rated_at, at(2).toISOString());
});

test('another organisation gets the same answer as for a ticket that does not exist', () => {
  const store = createStore();
  const t = resolved(store);
  assert.equal(portal.rateTicket(store, globex, t.id, 4), null);
  assert.equal(portal.rateTicket(store, globex, 9999, 4), null);
  assert.equal(portal.rateTicket(store, globex, t.id, 99), null); // org check comes before score check
  assert.equal(store.getTicket(t.id).rating_score, null);
});
```
