'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { createStore } = require('../src/store');
const { createTicket, assignTicket, resolveTicket } = require('../src/tickets');
const { drain } = require('../src/notify');
const portal = require('../src/portal');
const { summariseRatings, writeAgentCsat } = require('../src/jobs/agent-csat-summary');

const DAY = 24 * 60 * 60 * 1000;
const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);
const acme = { id: 7, orgId: 1 };

// A ticket owned by `agent`, resolved, rated `score` at day `ratedDay` (no rating when score is null).
function rated(store, agent, score, ratedDay) {
  const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'Printer', body: 'x', now: at(0) });
  if (agent) assignTicket(store, t.id, agent);
  resolveTicket(store, t.id, agent || 41, { now: at(1) });
  if (score !== null) portal.rateTicket(store, acme, t.id, score, { now: at(ratedDay) });
  return t;
}

function fixture() {
  const store = createStore();
  drain();
  rated(store, 41, 5, 19); // 1 day before "now"
  rated(store, 41, 4, 18);
  rated(store, 41, 1, 14); // 6 days before
  rated(store, 41, 5, 12); // 8 days before: not counted
  rated(store, 41, null, 0); // unrated
  rated(store, 42, 3, 12); // only an old rating: agent left out
  rated(store, null, 5, 19); // unassigned: not counted
  drain();
  return store;
}

test('an agent with ratings 5, 4 and 1 in the past seven days shows three ratings and an average of 3.33', () => {
  assert.deepEqual(summariseRatings(fixture(), { now: at(20) }), [{ agent_id: 41, ratings: 3, average: 3.33 }]);
});

test('a rating exactly seven days old is counted, one a moment older is not', () => {
  const store = createStore();
  rated(store, 41, 2, 13);
  assert.equal(summariseRatings(store, { now: at(20) })[0].ratings, 1);
  assert.deepEqual(summariseRatings(store, { now: new Date(at(20).getTime() + 1) }), []);
});

test('the job writes the summary file', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'helpdesk-csat-'));
  try {
    const out = writeAgentCsat(fixture(), { now: at(20), dir });
    assert.equal(out.agents, 1);
    assert.equal(path.basename(out.file), 'agent-csat-weekly.json');
    assert.deepEqual(JSON.parse(fs.readFileSync(out.file, 'utf8')), [{ agent_id: 41, ratings: 3, average: 3.33 }]);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});
```
