- [ ] 3. Create `src/jobs/agent-csat-summary.js`:
```js
'use strict';
// Nightly. Writes exports/agent-csat-weekly.json: for each agent, how many ratings their tickets received in the
// past seven days and the average score. Agents with no ratings in the window are left out.
const fs = require('node:fs');
const path = require('node:path');

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;
const EXPORT_DIR = path.join(__dirname, '..', '..', 'exports');

function summariseRatings(store, { now = new Date() } = {}) {
  const since = now.getTime() - WINDOW_DAYS * DAY;
  const byAgent = new Map();
  for (const t of store.listTickets()) {
    if (t.rating_score == null || !t.assignee_id) continue;
    if (new Date(t.rated_at).getTime() < since) continue;
    const s = byAgent.get(t.assignee_id) || { sum: 0, ratings: 0 };
    s.sum += t.rating_score;
    s.ratings += 1;
    byAgent.set(t.assignee_id, s);
  }
  return [...byAgent.entries()]
    .sort(([a], [b]) => a - b)
    .map(([agent_id, s]) => ({ agent_id, ratings: s.ratings, average: Math.round((s.sum / s.ratings) * 100) / 100 }));
}

function writeAgentCsat(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
  const rows = summariseRatings(store, { now });
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, 'agent-csat-weekly.json');
  fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
  return { file, agents: rows.length };
}

module.exports = { summariseRatings, writeAgentCsat, WINDOW_DAYS };
```
